import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * A context-free stand-in for `DropdownMenuItem`.
 *
 * `DropdownMenuItem` (Radix) only works when mounted inside an actual
 * `DropdownMenu.Root`/`Content` tree. Since MultiFilter's option lists are
 * rendered inside either a desktop `DropdownMenuContent` or a mobile
 * `DrawerContent` (see `ResponsiveFilterMenu`), list rows must not depend on
 * Radix menu context. This component replicates `DropdownMenuItem`'s look
 * and keyboard/selection behavior with a plain, focusable element so it can
 * be reused in both containers.
 */
function FilterMenuItem({
  className,
  disabled,
  onSelect,
  ref,
  ...props
}: React.ComponentProps<"div"> & {
  disabled?: boolean;
  onSelect?: (event: Event) => void;
  ref?: React.Ref<HTMLDivElement>;
}) {
  const triggerSelect = (event: React.SyntheticEvent) => {
    if (disabled) return;
    onSelect?.(event.nativeEvent);
  };

  return (
    <div
      ref={ref}
      role="menuitem"
      tabIndex={disabled ? -1 : 0}
      aria-disabled={disabled}
      data-slot="filter-menu-item"
      data-disabled={disabled}
      onClick={triggerSelect}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          triggerSelect(event);
        }
      }}
      className={cn(
        "focus:bg-gray-100 focus:text-gray-900 [&_svg:not([class*='text-'])]:text-gray-500 relative flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 dark:focus:bg-gray-800 dark:focus:text-gray-50 dark:[&_svg:not([class*='text-'])]:text-gray-400",
        className,
      )}
      {...props}
    />
  );
}

export default FilterMenuItem;

import * as React from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Drawer,
  DrawerContent,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";

import useBreakpoints from "@/hooks/useBreakpoints";

interface ResponsiveFilterMenuProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  trigger: React.ReactNode;
  children: React.ReactNode;
  /** Accessible title for the mobile drawer (visually hidden). */
  title: string;
  align?: "start" | "end";
  contentClassName?: string;
  drawerContentClassName?: string;
}

/**
 * Renders a trigger + content pair that behaves like a `DropdownMenu` on
 * desktop and a bottom `Drawer` on mobile, matching the responsive pattern
 * used by `Autocomplete`/`MultiSelect`. Used across MultiFilter so filter
 * pickers are touch-friendly on small screens.
 */
export default function ResponsiveFilterMenu({
  open,
  onOpenChange,
  trigger,
  children,
  title,
  align = "start",
  contentClassName,
  drawerContentClassName,
}: ResponsiveFilterMenuProps) {
  const { t } = useTranslation();
  const isMobile = useBreakpoints({ default: true, sm: false });

  if (isMobile) {
    return (
      <Drawer open={open} onOpenChange={onOpenChange}>
        <DrawerTrigger asChild>{trigger}</DrawerTrigger>
        <DrawerContent
          aria-describedby={undefined}
          className={cn(
            "min-h-[40vh] max-h-[85vh] px-0 pt-2 pb-0 rounded-t-lg flex flex-col",
            drawerContentClassName,
          )}
        >
          <DrawerTitle className="sr-only">{t(title)}</DrawerTitle>
          <div className="mt-4 pb-[env(safe-area-inset-bottom)] flex-1 overflow-y-auto">
            {children}
          </div>
        </DrawerContent>
      </Drawer>
    );
  }

  return (
    <DropdownMenu open={open} onOpenChange={onOpenChange}>
      <DropdownMenuTrigger asChild>{trigger}</DropdownMenuTrigger>
      <DropdownMenuContent
        className={cn("p-0", contentClassName)}
        align={align}
      >
        {children}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

